create or replace function public.crm_experiment_report(p_experiment_id uuid)
returns jsonb language sql stable set search_path=public
as $$
with e as (select id from public.crm_experiments where id=p_experiment_id and user_id=auth.uid()),
variants as (select v.id,v.name,v.weight,count(distinct x.subject_key)::int exposures,count(distinct case when o.outcome='converted' then o.subject_key end)::int conversions,coalesce(sum(case when o.outcome='revenue' then o.value else 0 end),0) revenue from public.crm_experiment_variants v join e on e.id=v.experiment_id left join public.crm_experiment_exposures x on x.variant_id=v.id left join public.crm_experiment_outcomes o on o.variant_id=v.id and o.subject_key=x.subject_key group by v.id,v.name,v.weight),
scored as (select *,case when exposures>0 then conversions::numeric/exposures else 0 end conversion_rate from variants),
intervals as (select s.*,case when exposures>0 then greatest(0,((conversion_rate+1.96^2/(2*exposures)-1.96*sqrt((conversion_rate*(1-conversion_rate)+1.96^2/(4*exposures))/exposures))/(1+1.96^2/exposures))) else 0 end ci_low,case when exposures>0 then least(1,((conversion_rate+1.96^2/(2*exposures)+1.96*sqrt((conversion_rate*(1-conversion_rate)+1.96^2/(4*exposures))/exposures))/(1+1.96^2/exposures))) else 0 end ci_high from scored s),
best as (select * from intervals where exposures>=100 order by conversion_rate desc,revenue desc,id limit 1),totals as (select coalesce(sum(exposures),0)::int exposures,coalesce(sum(conversions),0)::int conversions,coalesce(sum(revenue),0) revenue from intervals),
learning as (select coalesce(jsonb_agg(jsonb_build_object('variant_id',s.id,'name',s.name,'conversion_rate',round(s.conversion_rate,6),'lift_vs_best',case when b.conversion_rate>0 then round((s.conversion_rate-b.conversion_rate)/b.conversion_rate,6) else 0 end,'sample_size',s.exposures,'ci_95_low',round(s.ci_low,6),'ci_95_high',round(s.ci_high,6),'eligible_for_winner',s.exposures>=100,'confidence_level','95%_wilson_descriptive') order by s.conversion_rate desc),'[]'::jsonb) report from intervals s left join best b on true)
select jsonb_build_object('experiment_id',p_experiment_id,'variants',coalesce((select jsonb_agg(jsonb_build_object('variant_id',id,'name',name,'weight',weight,'exposures',exposures,'conversions',conversions,'conversion_rate',round(conversion_rate,6),'revenue',revenue,'ci_95_low',round(ci_low,6),'ci_95_high',round(ci_high,6)) order by name) from intervals),'[]'::jsonb),'totals',(select to_jsonb(totals) from totals),'learning',(select report from learning),'recommended_variant',(select jsonb_build_object('variant_id',id,'name',name,'conversion_rate',round(conversion_rate,6),'ci_95_low',round(ci_low,6),'ci_95_high',round(ci_high,6),'minimum_sample_size',100,'reason','Maior taxa de conversão observada entre variantes com pelo menos 100 exposições; intervalo Wilson de 95% é informativo e não prova causalidade.') from best),'generated_at',now());
$$;
